import Foundation
import Testing
@testable import AllInOneIMECore

/// The English words the key detector knows are a resource of the core (Resources/RedactionWords.txt, generated by
/// Scripts/make-redaction-words.swift): every system has them, and on a Mac they are the system's list as it was read.
struct RedactionWordListTests {
    /// Where the list came from (Scripts/make-redaction-words.swift).
    static let source = "/usr/share/dict/web2"
    static var sourceIsHere: Bool { FileManager.default.fileExists(atPath: source) }

    @Test func theWordsAreInTheCore() {
        #expect(RedactionWords.english.count == 234_291)
        for word in ["aal", "aardvark", "telephone", "kitchen", "zyzzogeton"] {
            #expect(RedactionWords.english.contains(word), "\(word)")
        }
        #expect(!RedactionWords.english.contains("") && !RedactionWords.english.contains("ab"))
        #expect(!RedactionWords.english.contains("Kitchen") && !RedactionWords.english.contains("kitchenx"))
    }

    /// The resource is found where SwiftPM put it for these tests; one the core doesn't have is nil, not a crash.
    @Test func theResourceIsFound() throws {
        let url = try #require(CoreResources.url(forResource: "RedactionWords", withExtension: "txt"))
        #expect(url.lastPathComponent == "RedactionWords.txt")
        #expect(url.path.contains(CoreResources.bundleName))
        #expect(CoreResources.url(forResource: "NoSuchResource", withExtension: "txt") == nil)
    }

    /// Searched as it lies, the file has to be sorted by bytes, a word a line, each line ended by LF (a checkout that
    /// turned it into CRLF would find nothing).
    @Test func theFileIsSortedAWordALine() {
        let words = RedactionWords.english.words
        #expect(words.count == RedactionWords.english.count)
        #expect(zip(words, words.dropFirst()).allSatisfy { $0.utf8.lexicographicallyPrecedes($1.utf8) })
        #expect(words.allSatisfy { $0.count >= 3 && $0.allSatisfy { $0.isASCII && ($0.isLowercase || $0 == "-") } })
    }

    /// Where the list came from is here (a Mac): the words are exactly its lines of 3 characters or more, lowercased,
    /// as the core read /usr/share/dict/words before.
    @Test(.enabled(if: sourceIsHere)) func theWordsAreTheSystemsList() throws {
        let text = try String(contentsOfFile: Self.source, encoding: .utf8)
        var words = Set<String>()
        for line in text.split(separator: "\n") where line.count >= 3 { words.insert(line.lowercased()) }
        #expect(Set(RedactionWords.english.words) == words)
        #if os(macOS)
        let system = try String(contentsOfFile: "/usr/share/dict/words", encoding: .utf8)
        #expect(system == text, "/usr/share/dict/words is web2")
        #endif
    }
}
